"""Supplementary COMP v2 check (CPU, scorer unchanged): share of REP_T / REP_A / OCR_V answers that START with the
instruction (normalised: lower case, punctuation and extra spaces removed). Needed because MiniCPM-o repeats the typed
sentence in a loop, which makes the 'exact' score falsely low. Output: comp2_startswith_pilot1000.md"""
import json, re, glob, os
def norm(s): return re.sub(r"\s+", " ", re.sub(r"[^\w\s]", " ", s.lower())).strip()
out = ["# COMP v2 supplementary: answer starts with the instruction (pilot1000)", "",
       "Generated by experiments/h1_v2/comp2_startswith.py. Exact = existing scorer; starts-with = normalised prefix match.", "",
       "| model | REP_T exact / starts-with % | REP_A exact / starts-with % | OCR_V exact / starts-with % |", "|---|---|---|---|"]
for m in ["qwen2.5-omni-7b", "qwen2.5-omni-3b", "minicpm-o-2.6", "phi-4-mm", "internomni"]:
    f = glob.glob(f"results/{m}/ocr_pilot1000_COMP2_*.jsonl")[0]
    rows = [json.loads(l) for l in open(f)]
    cells = []
    for c in ["REP_T", "REP_A", "OCR_V"]:
        rs = [r for r in rows if r["condition"] == c]
        sw = sum(norm(r["answer"]).startswith(norm(r["negation"])) for r in rs)
        ex = sum(bool(r.get("ocr_exact")) for r in rs) if "ocr_exact" in rs[0] else None
        cells.append(f"{'' if ex is None else f'{100*ex/len(rs):.1f} / '}{100*sw/len(rs):.1f} (n={len(rs)})")
    out.append(f"| {m} | " + " | ".join(cells) + " |")
open("comp2_startswith_pilot1000.md", "w").write("\n".join(out) + "\n"); print("\n".join(out))
